# Remove any conflicting functions in the global environment left over from sourcing scripts manually
suppressWarnings(rm(list = intersect(ls(envir = .GlobalEnv), c("open_nl", "sii", "calculate_loudness", "calculate_open_nl_gain")), envir = .GlobalEnv))

devtools::load_all(".", reset = TRUE)
source("R/sii.R")
source("R/open_nl.R")
source("R/benchmark_targets.R")

cat("Generating evaluate_amt_speech.m...\n")
m_code <- c(
  "% AMT Bramslow2004 Benchmark - Auto-generated by generate_amt_benchmark.R",
  "% Run with: octave --no-gui evaluate_amt_speech.m",
  "addpath('/home/mark/Desktop/amtoolbox-full-1.6.0/amtoolbox-1.6.0');",
  "amt_start;",
  "fs = 48000;",
  "fprintf('Evaluating A1-A7 Profiles for NAL-NL2 and Open-NL:\\n');",
  ""
)

profiles   <- c("a1", "a2", "a3", "a4", "a5", "a6", "a7")
aud_freqs  <- c(250, 500, 1000, 2000, 4000, 8000)  # standard audiometric frequencies

for (i in seq_along(profiles)) {
  p          <- profiles[i]
  target_data <- jd2011_targets[[p]]
  freqs      <- aud_freqs                           # always 6-point for LTASS
  threshold  <- target_data$threshold               # always at 6 standard freqs
  loss <- rep(0, 6)
  if (p == "a6") loss <- rep(30, 6)
  if (p == "a7") loss <- rep(50, 6)

  formulas <- c("NAL-NL2", "Open-NL")
  for (f in formulas) {
    cat(sprintf("  Processing %s - %s...\n", toupper(p), f))
    if (f == "Open-NL") {
      presc    <- open_nl(speech = 65, threshold = threshold, freq = freqs, loss = loss)
      gain_tgt <- presc$gain
      cat(sprintf("    Gain: %s\n", paste(round(gain_tgt, 1), collapse=", ")))
    } else {
      gain_tgt <- get_nalnl2_v2_target(p, f, target_freqs = freqs, level = 65)
    }
    
    target_level <- 65
    input_speech <- c(37.4, 36.92, 27.66, 19.97, 11.98, 3.78) + (target_level - 65)
    aided_spl <- input_speech + gain_tgt - loss
    
    f_half <- seq(0, 24000, by = 0.5)
    f_half[1] <- 1
    levels_interp <- approx(x = log10(freqs), y = aided_spl, xout = log10(f_half), rule = 2)$y
    idx_low <- which(f_half < freqs[1])
    if (length(idx_low) > 0) levels_interp[idx_low] <- aided_spl[1] - 24 * log2(freqs[1] / pmax(f_half[idx_low], 1))
    idx_high <- which(f_half > freqs[length(freqs)])
    if (length(idx_high) > 0) levels_interp[idx_high] <- aided_spl[length(aided_spl)] - 24 * log2(f_half[idx_high] / freqs[length(freqs)])
    overall <- 10 * log10(sum(10^(levels_interp/10)) * 0.5)
    
    dense_f <- seq(10, 23990, by = 10)
    dense_l <- approx(x = log10(freqs), y = aided_spl, xout = log10(dense_f), rule = 2)$y
    idx_low <- which(dense_f < freqs[1])
    if (length(idx_low) > 0) dense_l[idx_low] <- aided_spl[1] - 24 * log2(freqs[1] / dense_f[idx_low])
    idx_high <- which(dense_f > freqs[length(freqs)])
    if (length(idx_high) > 0) dense_l[idx_high] <- aided_spl[length(aided_spl)] - 24 * log2(dense_f[idx_high] / freqs[length(freqs)])
    current_spl <- 10 * log10(sum(10^(dense_l/10) * 10))
    offset <- overall - current_spl
    dense_l <- dense_l + offset
    
    sn_loss <- threshold - loss
    
    freq_str <- paste(dense_f, collapse = " ")
    lvl_str <- paste(dense_l, collapse = " ")
    ag_f <- c(125, 250, 500, 750, 1000, 1500, 2000, 3000, 4000, 6000, 8000, 10000, 12500)
    ag_loss <- approx(x = log10(freqs), y = sn_loss, xout = log10(ag_f), rule = 2)$y
    ag_loss_str <- paste(ag_loss, collapse = " ")
    
    m_code <- c(m_code, 
      sprintf("%% Profile %s - %s", toupper(p), f),
      sprintf("inputF = [%s];", freq_str),
      sprintf("inputLdB = [%s];", lvl_str),
      sprintf("ag_loss = [%s];", ag_loss_str),
      "t = (0:(fs-1))' / fs;",
      "insig = zeros(length(t), 1);",
      "for k = 1:length(inputF)",
      "  A = sqrt(2) * 10^((inputLdB(k) + 10*log10(10) - 94)/20);",
      "  insig = insig + A * sin(2*pi*inputF(k)*t + rand*2*pi);",
      "end",
      "outs = bramslow2004(insig, fs, 'AGLoss', ag_loss);",
      sprintf("fprintf('Profile %s (%s) Sones: %%f\\n', mean(outs.Loudness));", toupper(p), f),
      "fflush(stdout);",
      ""
    )
  }
}
writeLines(m_code, "evaluate_amt_speech.m")
cat("Generated evaluate_amt_speech.m\n")
